  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

reg [1:0] state, next_state;
reg walk_left_reg, walk_right_reg, aaah_reg;

// State encoding
localparam IDLE = 2'b00,
           WALK_LEFT = 2'b01,
           WALK_RIGHT = 2'b10,
           FALLING = 2'b11;

always @(posedge clk or posedge areset) begin
    if (areset)
        state <= IDLE;
    else
        state <= next_state;
end

// State transition logic
always @(*) begin
    next_state = state;
    walk_left_reg = 0;
    walk_right_reg = 0;
    aaah_reg = 0;

    case (state)
        IDLE:
            if (bump_left || bump_right) begin
                next_state = WALK_RIGHT;
            end else if (!ground) begin
                next_state = FALLING;
            end

        WALK_LEFT:
            if (bump_left || bump_right) begin
                next_state = WALK_RIGHT;
            end else if (!ground) begin
                next_state = FALLING;
            end

        WALK_RIGHT:
            if (bump_left || bump_right) begin
                next_state = WALK_LEFT;
            end else if (!ground) begin
                next_state = FALLING;
            end

        FALLING:
            if (ground) begin
                next_state = state; // Stay in falling until ground reappears
