module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output [23:0] out_bytes,
  output done
);

reg [1:0] state, next_state;
reg [23:0] message_buffer;
reg [1:0] byte_count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 2'b00;
        out_bytes <= 24'b0;
        done <= 1'b0;
        message_buffer <= 24'b0;
        byte_count <= 2'b00;
    end else begin
        state <= next_state;
        if (done) begin
            out_bytes <= message_buffer;
        end
    end
end

always @(*) begin
    case (state)
        2'b00: // IDLE
            if (in[3]) begin
                next_state = 2'b01;
                byte_count = 2'b00;
                message_buffer = {24{in}};
            end else begin
                next_state = 2'b00;
            end
        2'b01: // RECEIVE_FIRST_BYTE
            if (byte_count == 2'b00) begin
                next_state = 2'b02;
                byte_count = 2'b01;
                message_buffer = {24{in}};
            end else begin
                next_state = 2'b01;
            end
        2'b02: // RECEIVE_SECOND_BYTE
            if (byte_count == 2'b01) begin
                next_state = 2'b03;
                byte_count = 2'b10;
                message_buffer = {message_buffer[15:0], in};
            end else begin
                next_state = 2'b02;
            end
        2'b03: // RECEIVE_THIRD_BYTE
            if (byte_count == 2'b10) begin
                next_state = 2'b00;
                byte_count = 2'b00;
                message_buffer = {message_buffer[8:0], in};
                done = 1'b1;
            end else begin
                next_state = 2'b03;
            end
        default:
            next_state = 2'b00;
    endcase
end

endmodule

